-- 004: the 25 built-in tools become database rows so the owner can edit their text, commands, price and guide. Owner-only edit comes from tools_upd/tools_del (002). Safe to re-run.
insert into public.tools(slug,name,class,description_en,description_ar,commands,visibility,status,created_by)
select v.slug,v.name,v.class,v.den,v.dar,v.cmds,'public','published',(select id from public.profiles where role='owner' limit 1)
from (values
('scarosint','SCAROSINT','recon','Keyless reconnaissance for Kali Linux. DNS, web, TLS, archives and registration data for a domain you own, no API keys.','استطلاع OSINT بدون مفاتيح API على كالي لينكس: DNS والويب وTLS والأرشيف وبيانات التسجيل لدومين تملكه.',array['SCAROSINT your-owned-domain.com','SCAROSINT example.com --json --no-save > report.json']::text[]),
('scarlan','SCARLAN','recon','Local network inventory and exposure reporter. Lists hosts, open ports and services on a private range you own, and shows what changed since the last run.','جرد الشبكة المحلية وتقرير التعرّض: أجهزة ومنافذ وخدمات على شبكة خاصة بتاعتك، ويوريك إيه اللي اتغير من آخر مرة.',array['scarlan demo','scarlan scan --network 192.168.1.0/24 --i-own-this-network','scarlan diff']::text[]),
('scarports','SCARPORTS','recon','Offline reference for common network ports with a one-line security note for each. Look up by number or service name.','مرجع أوفلاين للبورتات الشائعة مع ملاحظة أمنية من سطر لكل واحد. دوّر بالرقم أو باسم الخدمة.',array['scarports 3389','scarports redis','scarports --json']::text[]),
('scarcustody','SCARCUSTODY','forensics','Evidence hashing with a tamper-evident chain-of-custody log. Each entry holds the hash of the previous one, so edits break the chain.','هاش للأدلة الرقمية مع سجل سلسلة حيازة مقاوم للتلاعب. كل سجل فيه هاش اللي قبله فأي تعديل بيكسر السلسلة.',array['scarcustody init --name CASE-042 --actor "Omar"','scarcustody add /mnt/usb/image.dd -n "seized from desk 3"','scarcustody verify --record']::text[]),
('scarlog','SCARLOG','forensics','Log analyzer for forensics and defense. Reads SSH/auth and web access logs, builds one timeline and reports observations such as brute force and probe paths.','محلل لوجات للتحقيق والدفاع. بيقرا لوجات SSH والويب، يعمل تايم لاين واحد، ويطلع ملاحظات زي brute force ومسارات الفحص.',array['scarlog --help']::text[]),
('scarioc','SCARIOC','forensics','Indicator of Compromise extractor. Pulls IPs, domains, URLs, emails, hashes and CVEs from logs and reports. Understands defanged input. Offline, stdlib only.','بيستخرج مؤشرات الاختراق (IPs، دومينات، روابط، إيميلات، هاشات، CVEs) من اللوجات والتقارير. بيفهم الصيغ المعطّلة وشغال أوفلاين.',array['scarioc incident.log','cat incident.log | scarioc -f json']::text[]),
('scartime','SCARTIME','forensics','Timestamp converter and log timeline merger. Understands Unix seconds, ms and us, Windows FILETIME, ISO 8601, syslog and web access log formats.','محوّل توقيتات ودامج لوجات في خط زمني واحد. بيفهم يونكس وويندوز FILETIME وISO 8601 وسيسلوج ولوجات الويب.',array['scartime convert 1700000000','scartime convert 133444736000000000','scartime merge auth.log access.log']::text[]),
('scarmeta','SCARMETA','forensics','File identifier. Detects the real type from magic bytes, flags extension mismatches and high-entropy (packed or encrypted) content.','محدد نوع الملفات. بيعرف النوع الحقيقي من magic bytes ويكشف عدم تطابق الامتداد والمحتوى عالي الإنتروبي (مضغوط أو مشفّر).',array['scarmeta suspicious_dir/','scarmeta invoice.pdf --json']::text[]),
('scarhash','SCARHASH','forensics','Hash files and verify sha256sum-style checksum lists. Reports OK, FAILED and MISSING for each file.','بصمات الملفات والتحقق من قوائم checksum بنفس صيغة sha256sum. بتعرض OK وFAILED وMISSING لكل ملف.',array['scarhash hash evidence.img','scarhash verify SHA256SUMS']::text[]),
('scarbase','SCARBASE','defense','File integrity baseline and drift checker. Hash a folder, save a baseline, later see exactly what was added, removed or changed.','مراقب سلامة الملفات. اعمل بصمة لمجلد واحفظها، وبعدين شوف بالظبط إيه اللي اتضاف أو اتمسح أو اتغيّر.',array['scarbase init /etc/myapp -b base.json','scarbase check -b base.json','scarbase check -b base.json --json']::text[]),
('scardiff','SCARDIFF','defense','Config diff that ignores comments, blank lines and whitespace. Shows only the lines that really changed.','مقارنة ملفات إعدادات بتتجاهل التعليقات والسطور الفاضية والمسافات. بتعرض بس السطور اللي اتغيّرت فعلاً.',array['scardiff sshd_config.old sshd_config.new','scardiff a.ini b.ini -c '';''']::text[]),
('scarheaders','SCARHEADERS','defense','HTTP security header checker. Grades the headers of a site you own and gives the one-line fix for each missing header.','فاحص هيدرز الأمان في HTTP. بيدّي تقدير لهيدرز موقع تملكه ويديك سطر الحل لكل هيدر ناقص.',array['scarheaders https://your-site.example --i-own-this','scarheaders https://your-site.example --i-own-this --json']::text[]),
('scarengage','SCARENGAGE','pentest','Penetration test engagement tracker. Client, authorization reference, validated scope, findings, evidence hashes and client-ready reports. No scanning features.','متتبع لمشاريع اختبار الاختراق: العميل، مرجع التصريح، النطاق، النتايج، هاشات الأدلة وتقارير جاهزة. من غير أي فحص.',array['scarengage demo','scarengage show ENG-900']::text[]),
('scarreport','SCARREPORT','pentest','Turns SCAROSINT JSON into a clean HTML and Markdown report with an executive summary, ordered findings and a simple fix for each.','بيحوّل تقرير SCAROSINT JSON لتقرير HTML وMarkdown نضيف: ملخص تنفيذي، نتايج مرتبة، وحل بسيط لكل ملاحظة.',array['scarreport report.json','scarreport report.json -f html -o reports/']::text[]),
('scarcvss','SCARCVSS','pentest','CVSS v3.1 base score calculator. Give it a vector, get the score and the severity. Checked against known vectors.','حاسبة درجة CVSS v3.1. اديها الـ vector واخد الدرجة والخطورة. متراجعة على vectors معروفة.',array['scarcvss CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H']::text[]),
('scarcipher','SCARCIPHER','crypto','Classical and modern encryption toolkit for learning. Caesar, Playfair, Hill, DES, 3DES and AES written from scratch and checked against NIST vectors.','أداة تشفير كلاسيكي وحديث للتعلّم. Caesar وPlayfair وHill وDES و3DES وAES متكتبين من الصفر ومتأكد منهم بمتجهات NIST.',array['python3 scarcipher.py','python3 scarcipher.py test']::text[]),
('scardecode','SCARDECODE','crypto','Encoder, decoder and analysis tool. base64, hex, URL, ROT13 and more, auto-detects chained encodings, decodes JWTs, identifies hash types.','أداة ترميز وفك ترميز وتحليل. base64 وhex وURL وغيرها، بتكشف الترميز المتداخل، بتفك JWT، وبتتعرف على نوع الهاش.',array['scardecode magic "VTJGc2RHVmtYMStCMFJBSm9BPT0="','scardecode jwt <token>','scardecode hashid 5f4dcc3b5aa765d61d8327deb882cf99']::text[]),
('scarpass','SCARPASS','crypto','Offline password auditor and generator. Estimates entropy, flags common passwords and patterns, makes random passwords and passphrases. Nothing is stored or sent.','مدقق ومولّد كلمات سر أوفلاين. بيقدّر الإنتروبي ويكشف الكلمات الشائعة والأنماط ويولّد كلمات سر وعبارات عشوائية. مفيش حاجة بتتخزن أو تتبعت.',array['scarpass audit ''MyP@ssw0rd''','scarpass gen -l 24','scarpass phrase -w 5']::text[]),
('scarjwt','SCARJWT','crypto','JSON Web Token decoder and auditor. Flags alg none, missing expiry, risky headers and sensitive claims, and checks HMAC signatures. Offline.','فاحص ومفكّك JSON Web Token. بيكشف alg none وغياب الانتهاء والهيدرز الخطرة والبيانات الحساسة، وبيتحقق من توقيعات HMAC. أوفلاين.',array['scarjwt decode TOKEN','scarjwt audit TOKEN','scarjwt verify TOKEN --secret KEY']::text[]),
('scardrone','SCARDRONE','mobile','Defensive drone-security toolkit for authorized labs: perimeter scan, software audit, MAVLink anomaly analysis, parameter audit and wireless posture.','أدوات أمن الدرون الدفاعية للمعامل المصرّح بيها: فحص المحيط، مراجعة السوفتوير، تحليل MAVLink، ومراجعة البارامترز.',array['periscan --network 192.168.1.0/24 --i-own-this-network','mavlog flight.tlog.csv','paramguard vehicle.param']::text[]),
('scargrab','SCARGRAB','mobile','Android app: paste or share a link, choose video or MP3/M4A and the quality, save to Downloads/SCARGRAB. Kotlin, Compose and yt-dlp. For personal use.','تطبيق أندرويد: الصق أو شارك لينك، اختار فيديو أو MP3/M4A والجودة، وينزل في Downloads/SCARGRAB. للاستخدام الشخصي.',array['./gradlew assembleDebug','adb install -r app/build/outputs/apk/debug/app-debug.apk']::text[]),
('scarperm','SCARPERM','mobile','Android permission explainer. Rates permissions from names or a decoded AndroidManifest.xml and says why each one matters.','شارح صلاحيات أندرويد. بيقيّم الصلاحيات من الأسماء أو من AndroidManifest.xml وبيقول ليه كل واحدة مهمة.',array['scarperm READ_SMS CAMERA','scarperm -m AndroidManifest.xml --json']::text[]),
('scarhub','SCARHUB','platform','One launcher for the whole SCAR toolkit: menu, install check, help and examples per tool, guided workflows, install and update from git.','لانشر واحد لكل أدوات SCAR: منيو، فحص التثبيت، شرح وأمثلة لكل أداة، وورك فلوز موجّهة، وتثبيت وتحديث.',array['git clone https://github.com/omar-alhelaly/SCARHUB.git','./install.sh && scarhub']::text[]),
('scarnote','SCARNOTE','platform','Terminal notes and cheatsheet manager. Local, searchable, tags, optional passphrase encryption, Markdown import and export.','مدير ملاحظات وشيتات في التيرمينال. محلي، بحث وتاجات، وتشفير اختياري بباسفريز.',array['scarnote seed','scarnote add -t "ssh tunnel" -c "ssh -L 8080:127.0.0.1:80 user@host" --tag networking','scarnote list --tag networking']::text[]),
('scarlist','SCARLIST','platform','Markdown checklists for engagements. Web, network and DFIR templates, tick items off and see progress. Exit code 1 while work remains.','قوائم مراجعة Markdown للمشاريع الأمنية. قوالب ويب وشبكات وDFIR، علّم البنود وشوف التقدم. كود خروج 1 طول ما فيه شغل متبقي.',array['scarlist init engagement.md --template web','scarlist done engagement.md 3','scarlist show engagement.md']::text[])
) as v(slug,name,class,den,dar,cmds)
where exists (select 1 from public.profiles where role='owner')
on conflict (slug) do nothing;
